function home(){return `<section class="home"><div class="hero"><div class="hero-copy"><div class="eyebrow">An investigator’s perspective</div><h1>Follow the evidence.<br><span>Explore the<br>connections.</span></h1><p>I’m Matthew Ryan. This is where I explore the intersection of investigation and technology—building tools to make complex information easier to examine and understand.</p><a class="primary-link" href="#projects/network">Explore my projects ${arrow}</a></div><a class="hero-display" href="#projects/network" aria-label="Explore the Network Analysis Tool"><div class="window-bar"><span>NETWORK ANALYSIS / CASE STUDY 01</span><span class="window-lights" aria-hidden="true"><i></i><i></i><i></i></span></div><img src="assets/feature-captures/01-network-overview.png" alt="Underbelly case-study network with portraits, names and relationship labels"><div class="image-caption">Making relationships visible <span>VIEW PROJECT ↗</span></div></a></div><div class="home-bottom"><div><h2 class="section-label">01 / THE APPROACH</h2><p class="intro-note">Investigation starts with questions. My projects explore how visual analysis and purpose-built software can help organise information, reveal connections and support closer examination.</p></div><div><h2 class="section-label">02 / PROJECT INDEX</h2><a class="project-link" href="#projects/network"><span>01</span><div>Network Analysis Tool<small>RELATIONSHIPS / VISUAL ANALYSIS</small></div>${arrow}</a><a class="project-link" href="#projects/face-finder"><span>02</span><div>Face Finder<small>FACE DETECTION / PORTRAIT CROPPING</small></div>${arrow}</a></div></div></section>`}
function about(){return `<section class="about-page"><div class="eyebrow">ABOUT MATTHEW RYAN</div><h1>A lifelong interest<br>in building software<span>_</span></h1><div class="about-copy"><p>My passion for software development began in 1983 with the Z80-powered Dick Smith VZ200. In the 1990s, I moved into Windows development with Visual Basic, C++ and Delphi, followed by Java and Enterprise Java in the 2000s.</p><p>My career has taken me across both government and private industry. The projects I have found most rewarding are those supporting Defence and law enforcement.</p><p>These days, I work in Java during the day and develop my own projects in Python in the evenings.</p></div><a class="primary-link" href="#projects/network">Explore my projects ${arrow}</a></section>`}
function sidebar(project){return `<aside class="sidebar"><p class="section-label">PROJECT DIRECTORY</p><a class="side-link ${project==='network'?'active':''}" href="#projects/network" ${project==='network'?'aria-current="page"':''}><small>01 / VISUAL ANALYSIS</small>Network Analysis Tool</a><a class="side-link ${project==='face-finder'?'active':''}" href="#projects/face-finder" ${project==='face-finder'?'aria-current="page"':''}><small>02 / IMAGE TOOLS</small>Face Finder</a><div class="sidebar-bottom"><span>RESEARCH IN PROGRESS</span>A collection of tools,<br>experiments and case studies.</div></aside>`}
function network(){return `<div class="breadcrumb">PROJECTS / <span>01 — NETWORK ANALYSIS</span></div><div class="project-heading"><div><h1>Network Analysis Tool<span style="color:var(--cyan)">_</span></h1><p>Exploring the relationships behind the information.</p></div><span class="badge">IN DEVELOPMENT</span></div><div class="project-columns"><section class="gallery" aria-label="Network Analysis Tool screenshots"><div class="gallery-top"><span>APPLICATION / <b id="slide-number">01</b></span><span>FEATURE SHOWCASE</span></div><div class="gallery-frame"><img id="gallery-image" src="assets/feature-captures/01-network-overview.png" alt=""><button class="expand" id="expand-image">View full size ↗</button></div><div class="gallery-caption"><div aria-live="polite" aria-atomic="true"><h2 id="slide-title"></h2><p id="slide-subtitle"></p></div><div class="arrows"><button class="arrow" id="previous" aria-label="Previous screenshot">←</button><button class="arrow" id="next" aria-label="Next screenshot">→</button></div></div><div class="dots" aria-label="Choose screenshot">${slides.map((s,i)=>`<button class="dot" data-slide="${i}" aria-label="Screenshot ${i+1}: ${s.title}" aria-current="${i===activeSlide}"></button>`).join('')}</div><button class="primary-link" id="play-demo" hidden>Play transform demo ▶</button><p class="case-note" id="case-note"></p><p class="case-note" id="case-sources"></p></section><aside class="description"><h2>FROM INFORMATION TO CONNECTIONS</h2><p>A visual workspace for examining people, events, places and the relationships between them.</p><p>Build a network, expand it with transforms and turn source photographs into structured entities.</p><h2>EXPLORE THE NETWORK</h2><p>Find connection paths between entities. Organise related records into named groups, then collapse or expand them as you explore. Switch to the Map tab to examine recorded locations in their geographic context.</p><h2>SHARE YOUR INVESTIGATION</h2><p>Export selected graph, timeline or map views to Microsoft PowerPoint. Add editable slide titles, observations and an optional assessment to prepare a briefing.</p><h2>KEEP THE SOURCE IN VIEW</h2><p>Imported portraits retain their source filename, file hash and crop coordinates. The broader provenance system records transform inputs and histories to support review of how derived information was created.</p><dl><dt>FOCUS</dt><dd>Investigation &amp; relationship analysis</dd><dt>WORKSPACES</dt><dd>Investigation Notebook<br>Investigation Lab</dd><dt>FEATURES</dt><dd><ul class="shown-examples"><li>Network mapping</li><li>Transforms</li><li>Photo import</li><li>Connection paths</li><li>Groupings</li><li>Maps</li><li>PowerPoint export</li><li>Provenance</li></ul></dd></dl><div class="tag-list"><span class="tag">Networks</span><span class="tag">Transforms</span><span class="tag">Photo import</span><span class="tag">Provenance</span></div></aside></div>`}
function updateSlide(){
 const s=slides[activeSlide];
 const img=document.querySelector('#gallery-image');
 img.width=s.width;img.height=s.height;
 img.src='assets/'+s.image;img.alt=s.alt;
 const play=document.querySelector('#play-demo');
 const label=s.demoLabel||'transform demo';
 play.hidden=!s.animation;play.textContent='Play '+label;
 play.setAttribute('aria-pressed','false');
 play.onclick=()=>{
  const playing=play.dataset.playing==='true';
  img.src='assets/'+(playing?s.image:s.animation);
  img.alt=playing?s.alt:(s.animationAlt||s.alt);
  play.dataset.playing=String(!playing);
  play.setAttribute('aria-pressed',String(!playing));
  play.textContent=playing?'Play '+label:'Stop animation';
 };
 play.dataset.playing='false';
 document.querySelector('#slide-number').textContent=String(activeSlide+1).padStart(2,'0');
 document.querySelector('#slide-title').textContent=s.title;
 document.querySelector('#slide-subtitle').textContent=s.subtitle;
 document.querySelector('#case-note').textContent=s.note;
 const sources=document.querySelector('#case-sources');sources.replaceChildren();
 for(const [label,url] of s.sources||[]){
  if(sources.childNodes.length)sources.append(' / ');
  const link=document.createElement('a');link.href=url;link.textContent=label;
  link.target='_blank';link.rel='noopener noreferrer';sources.append(link);
 }
 sources.hidden=!s.sources;
 document.querySelectorAll('[data-slide]').forEach((b,i)=>b.setAttribute('aria-current',String(i===activeSlide)));
}

function articles(){return `<section class="articles-index"><div class="eyebrow">FIELD NOTES / ARTICLES</div><h1>Behind the graph<span>_</span></h1><p class="article-lead">The ideas and implementation decisions behind my investigation tools.</p><a class="article-card" href="#articles/provenance"><span class="section-label">01 / TECHNICAL NOTES</span><h2>How We Implement Provenance</h2><p>From a connection on screen to the information and analytical steps behind it. Explore the approach, a simple workflow and a fictional investigation.</p><span class="article-card-link">Read the article ↗</span></a><a class="article-card" href="#articles/overtime-deception"><span class="section-label">02 / CASE STUDY</span><h2>The Overtime Deception</h2><p>A fictional Brisbane case showing how GraphScene connects surveillance reports, timelines and places.</p><span class="article-card-link">Read the article ↗</span></a><a class="article-card" href="#articles/ndis-billing-review"><span class="section-label">03 / CASE STUDY</span><h2>Billed but not delivered?</h2><p>A fictional Brisbane NDIS billing review follows six claims through bookings, service records and payments.</p><span class="article-card-link">Read the article ↗</span></a><a class="article-card" href="#articles/mapping-a-complex-story"><span class="section-label">04 / CASE STUDY</span><h2>Mapping a Complex Story with GraphScene</h2><p>Follow a sourced investigation through Graph, Timeline and Map using selected records concerning Jared Kushner.</p><span class="article-card-link">Read the article ↗</span></a></section>`}
function provenance(){return `<div class="projects-shell articles-shell"><aside class="sidebar"><a class="section-label" href="#articles">← ALL ARTICLES</a><a class="side-link active" href="#articles/provenance" aria-current="page"><small>01 / TECHNICAL NOTES</small>How We Implement Provenance</a><div class="sidebar-bottom"><span>BEHIND THE GRAPH</span>Methods, decisions<br>and work in progress.</div></aside><article class="provenance-article" aria-labelledby="article-title"><div class="breadcrumb"><a href="#articles">ARTICLES</a> / <span>01 — PROVENANCE</span></div><header class="article-hero"><div class="eyebrow">NETWORK GRAPH ANALYSIS TOOL / TECHNICAL NOTES</div><h1 id="article-title">How We Implement<br><span>Provenance</span></h1><p class="article-lead">A connection is more useful when you can explain where it came from.</p><p class="article-meta">IMPLEMENTATION REVIEW · 24 OCTOBER 2026</p></header><nav class="article-contents" aria-label="Article sections"><a href="#articles/provenance/meaning">01 / The idea</a><a href="#articles/provenance/workflow">02 / The workflow</a><a href="#articles/provenance/example">03 / An example</a></nav>
<section id="meaning" class="article-section"><div class="eyebrow">01 / THE IDEA</div><h2>Keep the story behind the connection.</h2><p>In social network analysis, a graph brings people, organisations, places and events together. Provenance is the record of where that information came from and how it became part of the graph. It helps answer: “Why is this here, and what supports it?”</p><p>A line between two people can represent a reported meeting, a shared address or an analyst’s interpretation. Those meanings are different. Preserving the source and the steps behind a connection helps a reviewer assess it without relying on the picture alone.</p><h3>How Graph App Scene approaches this</h3><p>The implementation contains records that connect analytical operations to their inputs and investigation context. The transform engine prepares provenance with a transform identifier, source node, input node identifiers and a hypothesis identifier. Transformations are operations that derive information from existing entities—for example, extracting a domain from an email address.</p><p>The core model also defines creation records linking an entity to a run, a hypothesis and a causal step. A run inspector adapter is written to retrieve a run’s inputs and outputs. Together, these components provide a foundation for following derived information back through the operations that produced it.</p><p>This matters when reviewing a result, revisiting an assumption or explaining how a network developed. A source can be unreliable and an interpretation can be wrong even when its history is well recorded. Provenance makes that history inspectable; it does not establish that the information is true.</p><aside class="article-note"><strong>What has been verified?</strong><p>The descriptions above are based on a review of local implementation files. This is not an end-to-end certification of every application workflow. Automatic capture of every edit, complete source-document lineage, tamper-proof records and legal admissibility have not been established by this review.</p></aside></section>
<section id="workflow" class="article-section"><div class="eyebrow">02 / THE WORKFLOW</div><h2>From information to a reviewable network.</h2><p>An investigation starts with material to examine. The analyst records entities and relationships, derives further information where appropriate, and reviews what each connection actually supports.</p><figure class="workflow-figure"><figcaption><span>INVESTIGATIVE WORKFLOW</span><span class="illustration-label">CONCEPTUAL ILLUSTRATION</span></figcaption><ol class="workflow"><li><small>01 / COLLECT</small><strong>Source material</strong><p>Record a document or observation and its reference.</p></li><li><small>02 / RECORD</small><strong>Build the network</strong><p>Add entities and describe the observed relationships.</p></li><li><small>03 / DERIVE</small><strong>Run an operation</strong><p>Link derived information to its inputs and run.</p></li><li><small>04 / REVIEW</small><strong>Follow the lineage</strong><p>Examine the origin, steps and limits of a result.</p></li></ol><div class="lineage-strip">REVIEW BACKWARDS ← Result → operation → input → source reference</div></figure><p class="figure-note">This is a recommended analytical workflow. It combines source-handling practices with the provenance concepts found in the code; it does not depict a verified sequence of application screens.</p></section>
<section id="example" class="article-section"><div class="eyebrow">03 / AN EXAMPLE</div><h2>One shared domain. A question to investigate.</h2><p>Imagine an enquiry into a suspected equipment theft. Two fictional interview notes list contact addresses for Alex Vale and Sam Reed. An analyst wants to explore whether those addresses point to a shared organisation.</p><p class="fiction-label">All names, records, addresses and run labels below are invented. The reserved .example domain is used for illustration. No Paris attacks dataset or real criminal allegation is used.</p><figure class="workflow-figure example-figure"><figcaption><span>ENQUIRY / EQUIPMENT THEFT</span><span class="illustration-label">FICTIONAL DATA · CONCEPTUAL LINEAGE</span></figcaption><div class="example-lanes"><div class="example-lane"><div class="lineage-node source"><small>SOURCE S-01 · INTERVIEW NOTE</small><strong>Alex Vale</strong><span>Contact recorded: alex@harbour.example</span></div><div class="lineage-connector">↓ Analyst records the stated address</div><div class="lineage-node"><small>INPUT E-01 · EMAIL ENTITY</small><strong>alex@harbour.example</strong><span>Source reference in this example: S-01</span></div><div class="lineage-connector">↓ Run R-01 · extract email domain</div></div><div class="example-lane"><div class="lineage-node source"><small>SOURCE S-02 · INTERVIEW NOTE</small><strong>Sam Reed</strong><span>Contact recorded: sam@harbour.example</span></div><div class="lineage-connector">↓ Analyst records the stated address</div><div class="lineage-node"><small>INPUT E-02 · EMAIL ENTITY</small><strong>sam@harbour.example</strong><span>Source reference in this example: S-02</span></div><div class="lineage-connector">↓ Run R-02 · extract email domain</div></div></div><div class="lineage-node derived"><small>SHARED DERIVED VALUE · DOMAIN</small><strong>harbour.example</strong><span>R-01 from E-01 · R-02 from E-02 · hypothesis H-01</span></div><div class="lineage-connector">↓ Analyst assesses the result</div><div class="lineage-node assessment"><small>ANALYTICAL QUESTION · NOT AN ESTABLISHED RELATIONSHIP</small><strong>Do the contacts relate to the same organisation?</strong><span>A matching domain alone does not establish that Alex and Sam know each other or were involved in an offence.</span></div></figure><p class="figure-note">The diagram brings matching values together for clarity. It does not assert automatic entity merging, automated interview extraction or automatic source-reference capture.</p><h3>Read one result backwards</h3><p>For the first branch: <strong>harbour.example ← R-01 ← E-01 ← S-01.</strong> The domain is derived from the email address; the address is attributed to an interview note. A reviewer can ask whether the address was transcribed correctly, whether the note is reliable and whether the inference goes beyond what the source supports.</p><div class="lineage-table-wrap"><table class="lineage-table"><caption>What is illustrated, and what the implementation supports</caption><thead><tr><th scope="col">Example element</th><th scope="col">Status and meaning</th></tr></thead><tbody><tr><th scope="row">Inputs E-01 / E-02; runs R-01 / R-02</th><td>Illustrative identifiers. Transform provenance has fields for inputs and transform identity; creation records have a run identifier.</td></tr><tr><th scope="row">Hypothesis H-01</th><td>Illustrative investigation context. Hypothesis identifiers are present in provenance records.</td></tr><tr><th scope="row">References S-01 / S-02</th><td>Conceptual source documentation. Complete automatic document-to-entity lineage was not verified.</td></tr><tr><th scope="row">Shared domain and assessment</th><td>A worked analytical example, not a captured application result or an automated finding.</td></tr></tbody></table></div></section>
<section class="article-section implementation-note"><h2>Implementation notes</h2><p>Reviewed locally: the transform engine and result model, graph provenance model, entity creation records, provenance ledger and run inspector adapter. The ledger includes run listing and hash-generation code; their presence alone does not establish a complete, tamper-proof audit trail.</p><details><summary>Files behind this explanation</summary><ul><li><code>core/transforms/platform/transform_engine.py</code></li><li><code>core/transforms/platform/transform_result.py</code></li><li><code>core/graph/provenance.py</code></li><li><code>core/model/birth_provenance.py</code></li><li><code>core/engine/provenance_ledger.py</code></li><li><code>core/ui/run_inspector_adapter.py</code></li></ul></details><a class="primary-link" href="#projects/network">Explore Graph App Scene ↗</a></section></article></div>`}

const faceFinderScreenshot = {image:'face-finder.png', title:'Face Finder — detect, select and copy', alt:'Face Finder displaying a photograph of Bill and Nancy Hamilton, two detected faces, the selected portrait with 4:5 framing and a Copy to clipboard button.'};
function faceFinder(){return `<div class="breadcrumb">PROJECTS / <span>02 - FACE FINDER</span></div><div class="project-heading"><div><h1>Face Finder<span style="color:var(--cyan)">_</span></h1><p>From a photograph to a ready-to-paste portrait.</p></div><span class="badge">IN DEVELOPMENT</span></div><div class="project-columns"><section class="gallery" aria-label="Face Finder screenshot"><div class="gallery-top"><span>APPLICATION / 01</span><span>DETECT / SELECT / COPY</span></div><div class="gallery-frame"><img src="assets/face-finder.png" width="1576" height="1123" style="clip-path:inset(2px)" alt="${faceFinderScreenshot.alt}"><button class="expand" id="expand-face-finder">View full size ↗</button></div><div class="gallery-caption"><div><h2>Find a face. Frame a portrait.</h2><p>Open an image, detect faces and copy your selection.</p></div></div><p class="case-note">Captured from the running Python application: two faces detected in a photograph of Bill and Nancy Hamilton, with 4:5 portrait framing and one portrait selected, ready to copy to the clipboard.</p></section><aside class="description"><h2>PORTRAITS WITHOUT THE REPETITION</h2><p>Face Finder opens an image, detects the faces it contains and lets you select a face crop to copy to the operating system clipboard for use in another application.</p><p>Prepare portraits for reports, presentations or visual analysis without repeatedly drawing and cropping selections by hand. Images are processed locally on your computer.</p><h2>CHOOSE THE FRAME</h2><p>Review detected faces as thumbnails and preview your selection. Choose the detected face, a square portrait, a 4:5 portrait or an estimated head-and-shoulders frame. Custom horizontal and vertical margins give you further control in detected-face mode.</p><h2>FROM .NET TO PYTHON</h2><p>Face Finder is inspired by and builds upon <a href="https://sourceforge.net/projects/snfacecrop/" target="_blank" rel="noopener noreferrer">SNFaceCrop</a>, the open-source Windows face detection and cropping application. Ported from the .NET implementation to Python using PySide6 and OpenCV, this version extends the original workflow with live portrait framing presets and an estimated head-and-shoulders crop, alongside thumbnail previews and clipboard copying.</p><dl><dt>FOCUS</dt><dd>Face detection &amp; portrait cropping</dd><dt>WORKFLOW</dt><dd>Open image → Detect → Select → Copy</dd><dt>IMAGE FORMATS</dt><dd>BMP, JPEG and PNG</dd><dt>TECHNOLOGY</dt><dd>Python / PySide6 / OpenCV</dd></dl><div class="tag-list"><span class="tag">Python</span><span class="tag">Computer vision</span><span class="tag">Desktop application</span></div></aside></div>`}

function overtimeDeception(){return "<section class=\"provenance-article\"><a class=\"section-label\" href=\"#articles\">← ALL ARTICLES</a><article aria-labelledby=\"overtime-title\"><header class=\"article-hero\"><div class=\"eyebrow\">NETWORK GRAPH ANALYSIS TOOL / CASE STUDY</div><h1 id=\"overtime-title\">He said he was working late. What did the reports show?</h1></header><div class=\"article-section\"><p><em>The Overtime Deception is a fictional GraphScene showcase. The people, venues and observations are invented. Map pins are illustrative Brisbane-area anchors.</em></p><p>On 4 November 2025, Alex Rowan reported that Daniel had said he would finish work at 21:00. In the fictional surveillance report for that evening, investigator Jordan Vale recorded Daniel leaving his workplace at 17:35. One discrepancy raises a question. Seven evenings of reports give us enough context to see when it recurs and when it doesn't.</p><p>Published agency accounts inspired the scenario's repeated overtime explanations, visits to the same venue and ordinary comparison evenings.<sup><a href=\"#articles/overtime-deception/ref-1\">[1]</a></sup></p><h2>From report to Graph</h2><p>In report SR01, line SR01:01 records the 17:35 workplace exit. Lines SR01:02 and SR01:03 record entry to Lantern House at 18:10 and departure at 19:45. Line SR01:04 records arrival in the home area at 21:12. The client's account lives separately in CL01, with the communication time recorded as unknown.</p><p>GraphScene connects each observation to its report and location. The overview shows selected observations from all seven evenings. The expanded project adds the remaining observations and client claim records.</p><figure class=\"overtime-figure\"><a href=\"assets/overtime-deception/graph.png\" aria-label=\"Open full-size figure\"><img loading=\"lazy\" src=\"assets/overtime-deception/graph.png\" alt=\"GraphScene overview showing surveillance reports linked to selected observations and fictional locations\"></a><figcaption>GraphScene overview showing surveillance reports linked to selected observations and fictional locations</figcaption></figure><p><a href=\"assets/overtime-deception/graph-full.png\">View the expanded graph with all 50 nodes</a>.</p><h2>Read the sequence in Timeline</h2><p>The expanded Timeline shows all 26 observations across seven evenings. Hovering over the 19:50 departure from Lantern House on 11 November reveals the date, location and observation detail. The report records Daniel leaving the venue and leaves his activity inside unverified.</p><figure class=\"overtime-figure\"><a href=\"assets/overtime-deception/timeline-full.png\" aria-label=\"Open full-size figure\"><img loading=\"lazy\" src=\"assets/overtime-deception/timeline-full.png\" alt=\"GraphScene Timeline showing 26 observations and the open tooltip for the 19:50 Lantern House departure on 11 November\"></a><figcaption>GraphScene Timeline showing 26 observations and the open tooltip for the 19:50 Lantern House departure on 11 November</figcaption></figure><figure class=\"overtime-figure\"><a href=\"assets/overtime-deception/departure-comparison.svg\" aria-label=\"Open full-size figure\"><img loading=\"lazy\" src=\"assets/overtime-deception/departure-comparison.svg\" alt=\"Paired bars comparing workplace exit and reported work finish for all seven evenings\"></a><figcaption>Paired bars comparing workplace exit and reported work finish for all seven evenings</figcaption></figure><p>On five evenings, the reported finish was 3 hours 16 minutes to 3 hours 52 minutes later than the observed workplace exit. The two comparison evenings differed by 8 and 12 minutes. The chart compares two clock times. The reports leave gaps in coverage and do not establish whether Daniel worked elsewhere after leaving.</p><h2>Place the observations on the Map</h2><p>In the fictional case, the workplace in Red Hill is where investigators recorded Daniel’s departures, and Lantern House in East Brisbane is where they observed him entering on five evenings when he was reportedly working late. The café in Spring Hill and the grocery stop in West End were ordinary stops on two separate comparison evenings, while the home area in Yeronga marks the last recorded observation each evening.</p><figure class=\"overtime-figure\"><a href=\"assets/overtime-deception/map.png\" aria-label=\"Open full-size figure\"><img loading=\"lazy\" src=\"assets/overtime-deception/map.png\" alt=\"GraphScene Map showing five fictional locations, labelled Brisbane suburbs and the Brisbane River\"></a><figcaption>GraphScene Map showing five fictional locations, labelled Brisbane suburbs and the Brisbane River</figcaption></figure><p>The Brisbane River (Maiwar) and suburb boundaries give readers a shared geographic reference. Each pin represents a place mentioned in the reports. The reports record discrete observations with gaps between them.</p><h2>Evidence limits and safeguards</h2><p>The reports show a recurring discrepancy between the client-reported finish and the observed workplace exit. They cover seven selected evenings and leave gaps between observations. Activity inside Lantern House and any work after departure remain unknown.</p><p>This fictional Brisbane case shows how GraphScene can organise surveillance observations. Queensland Government guidance and police evidence to Parliament put that example in local context by explaining how monitoring and tracking can form part of stalking or coercive control.</p><p><strong>Queensland Government guidance on coercive control</strong> lists “using tracking devices to monitor your whereabouts unreasonably or without your consent” as an example of technology-based abuse. Its guidance also describes intrusive device checks and persistent demands to account for where someone is and who they are with.<sup><a href=\"#articles/overtime-deception/ref-2\">[2]</a></sup></p><p><strong>Queensland Police Service guidance on stalking</strong> identifies “Monitoring or tracking or surveilling a person’s movements, activities or interpersonal associations without the person’s consent, including using technology” as conduct that may form part of stalking. The guidance also describes following and watching a person. The circumstances and effect of the conduct matter whether or not a device is involved.<sup><a href=\"#articles/overtime-deception/ref-3\">[3]</a></sup></p><p><strong>Queensland Police Service evidence to Parliament</strong> explains how GPS can help perpetrators control a partner “by monitoring their location and limiting their movement both during the relationship and even post-separation.” In its response about vehicle trackers, QPS situates that conduct within a broader pattern of dominance and control.<sup><a href=\"#articles/overtime-deception/ref-4\">[4]</a></sup></p><p>The showcase uses invented people and approximate location pins. Its source pack excludes GPS traces, intercepted communications and private-account records. GraphScene keeps the client’s account separate from the investigator’s observations so readers can compare the two while seeing where the evidence ends.</p><h2>References</h2><ol><li id=\"ref-1\">Direct Focus Investigations, <a href=\"https://www.directfocusinvestigations.com/infidelity-case-study/\">Infidelity Case Study</a>. Kinsey Investigations, <a href=\"https://www.privateinvestigatorinlosangeles.com/post/massage-parlor-infidelity-investigations-surveillance-evidence-gathering-female-private-investigator\">recurring venue case study</a>. Resilient Investigations, <a href=\"https://resilientinvestigations.com/infidelity-surveillance-two-quiet-nights-before-the-pattern-changed/\">Two Quiet Nights Before The Pattern Changed</a>. These are agency accounts used as narrative inspiration.</li><li id=\"ref-2\">Queensland Government, <a href=\"https://www.qld.gov.au/initiative/need-to-know/coercive-control/spot-the-signs-of-coercive-control\">Spot the signs of coercive control</a>, “Using technology to abuse or control you”.</li><li id=\"ref-3\">Queensland Police Service, <a href=\"https://www.police.qld.gov.au/domestic-violence/unlawful-stalking-intimidation-harassment-and-abuse\">Unlawful stalking, intimidation, harassment and abuse</a>, “What is unlawful stalking, intimidation, harassment and abuse?”</li><li id=\"ref-4\">Queensland Police Service, <a href=\"https://documents.parliament.qld.gov.au/com/TRC-645B/IVSSTEIT-327D/cor-15Jul2021_QPS.pdf#page=14\">Question on Notice response to the Queensland Parliament Transport and Resources Committee</a>, 1 July 2021, Question 12(a), PDF page 14.</li></ol></div></article></section>"}

function ndisBillingReview(){return "<section class=\"provenance-article\"><a class=\"section-label\" href=\"#articles\">← ALL ARTICLES</a><article aria-labelledby=\"ndis-title\"><header class=\"article-hero\"><div class=\"eyebrow\">NETWORK GRAPH ANALYSIS TOOL / CASE STUDY</div><h1 id=\"ndis-title\">Billed but not delivered? Following an NDIS claim through GraphScene</h1></header><div class=\"article-section\"><p><em>This fictional Brisbane billing review uses invented participants, provider records and payments. Map pins represent approximate suburb areas.</em></p><p>A payment tells a reviewer that a claim was paid. To understand what supports it, the reviewer needs to follow the claim back to the booking and the service record.</p><p>In this example, Provider A submits six claims for support scheduled in Red Hill, West End and Yeronga. Two claims match their service notes. Two conflict with cancellation confirmations. One has a missing record, and another has a note covering only part of the billed time. GraphScene brings those records together so the reviewer can inspect the differences.</p><h2>A question grounded in published investigations</h2><p>The NDIA’s May 2026 account of Operation Benz describes a Queensland investigation into alleged claims for services that were never provided. The release reports searches at five business and residential properties and further analysis of seized records. It states that no charges had been laid at the time of that release.<sup><a href=\"#articles/ndis-billing-review/ndis-ref-1\">[1]</a></sup></p><p>That published investigation supplies context for the question explored here. Our small, invented billing review follows six claims through their supporting documents and payments. Its findings concern the evidence available for each claim.</p><h2>Follow the records in the Graph</h2><p>Each column in the expanded Graph follows a booking through its supporting record, claim and payment. The participants appear on the left and the service areas on the right. The three review events below record the opening of the review, a request for records and the completed comparison.</p><figure class=\"overtime-figure\"><a href=\"assets/ndis-billing-review/graph.png\" aria-label=\"Open full-size figure\"><img loading=\"lazy\" src=\"assets/ndis-billing-review/graph.png\" alt=\"Expanded GraphScene graph showing six bookings, supporting records, claims and payments, with three participants and four suburb areas\"></a></figure><p><em>Six fictional claims linked to bookings, supporting records and payments. E02 and E05 record cancellations. The empty position above C03 reflects its missing service record.</em></p><p>C01 gives us a reconciled example. Its booking is linked to a service note recording 120 minutes, and its claim bills 120 minutes. Following the same chain for C02 reaches a cancellation confirmation, while the claim bills 90 minutes of delivered support. C05 presents the same kind of conflict with a 120-minute claim.</p><p>The gap above C03 is a different problem. Its 120-minute claim has a booking and a payment, but the review pack contains no service record for the visit. The reviewer needs further records to establish what happened. C06 has a service note, but it records 60 minutes against 90 billed.</p><h2>Put the sequence in the Timeline</h2><p>The Timeline displays all 26 dated events. It places the booking times, cancellation confirmations, service notes, claim submissions, payments and review actions in sequence. A booked start remains visible even when the supporting record says the visit was cancelled.</p><figure class=\"overtime-figure\"><a href=\"assets/ndis-billing-review/timeline.png\" aria-label=\"Open full-size figure\"><img loading=\"lazy\" src=\"assets/ndis-billing-review/timeline.png\" alt=\"GraphScene Timeline with 26 events and a tooltip for C01 showing 120 billed minutes, 120 documented minutes and a reconciled review status\"></a></figure><p><em>Twenty-six events place bookings, records, claims, payments and review actions in sequence. The open tooltip shows C01, where all 120 billed minutes reconcile with the service note.</em></p><p>The tooltip gives the reader a way into the records behind a point on the screen. Here it exposes the claim’s billed minutes, documented minutes and review status. The same approach lets the reviewer inspect a cancellation conflict or an unresolved record.</p><h2>Compare billed and documented minutes</h2><figure class=\"overtime-figure\"><a href=\"assets/ndis-billing-review/billed-versus-documented.svg\" aria-label=\"Open full-size figure\"><img loading=\"lazy\" src=\"assets/ndis-billing-review/billed-versus-documented.svg\" alt=\"Paired bars compare six claims with their available service records, including an explicit unknown value for C03\"></a></figure><p><em>Six fictional claims compared with the available service records. C01 and C04 reconcile, C02 and C05 conflict with cancellation confirmations, C03 has unknown delivery because its record is missing, and C06 has 60 documented minutes against 90 billed.</em></p><p>C02 and C05 show zero service minutes because their cancellation confirmations explicitly record that no replacement service took place for those visits. C03 shows “Unknown” because the service record is missing. C06’s 30-minute difference remains unresolved.</p><p>All six claims in this example were submitted as delivered support. For the cancellation conflicts, the reviewer would examine the basis of each claim and any separate cancellation entitlement. The comparison records the questions that require follow-up.</p><figure class=\"overtime-figure\"><a href=\"assets/ndis-billing-review/claim-review-status.svg\" aria-label=\"Open full-size figure\"><img loading=\"lazy\" src=\"assets/ndis-billing-review/claim-review-status.svg\" alt=\"Review status chart showing two reconciled claims, two cancellation conflicts, one missing record and one partial documentation case\"></a></figure><p><em>Two claims reconcile. Two cancellation conflicts, one missing record and one partly documented service require further review. These counts describe the six-claim fictional sample.</em></p><h2>Locate the scheduled services on the Map</h2><p>The provider’s office area is in Milton. The scheduled service areas are in Red Hill, West End and Yeronga. The Brisbane River and suburb boundaries give the reviewer and a reader familiar with Brisbane a shared geographic reference.</p><figure class=\"overtime-figure\"><a href=\"assets/ndis-billing-review/map.png\" aria-label=\"Open full-size figure\"><img loading=\"lazy\" src=\"assets/ndis-billing-review/map.png\" alt=\"GraphScene Map showing the provider office area in Milton and scheduled service areas in Red Hill, West End and Yeronga, with the Brisbane River and suburb boundaries\"></a></figure><p><em>The fictional provider’s office area in Milton and scheduled service areas in Red Hill, West End and Yeronga. Illustrative suburb markers include bookings that were later cancelled.</em></p><p>The map helps a reader understand the service footprint and organise enquiries by area. The underlying records determine which bookings have documented delivery. Each pin represents an approximate area, with participant identities represented by fictional codes.</p><h2>What the review establishes</h2><p>The records support two reconciled claims and identify four claims for further enquiry. The six payments total $630 at the example’s invented rate of $60 per hour. A reviewer can follow each paid claim to the records that support it, see a cancellation conflict and identify where further documentation is needed.</p><p>A fraud finding would require further evidence about the claim circumstances and intent. This example finishes at a documented review position, ready for follow-up.</p><h2>References</h2><ol><li id=\"ndis-ref-1\">National Disability Insurance Agency, <a href=\"https://www.ndis.gov.au/news/11511-fraud-fusion-taskforce-seizes-millions-cash-gold-silver-and-other-property-during-ndis-fraud-investigation\">Fraud Fusion Taskforce seizes millions in cash, gold, silver and other property during NDIS fraud investigation</a>, joint release with the Queensland Crime and Corruption Commission, 4 May 2026. The case status described above is explicitly the status reported in that release.</li></ol></div></article></section>"}

function mappingComplexStory(){return "<section class=\"provenance-article\"><a class=\"section-label\" href=\"#articles\">← ALL ARTICLES</a><article aria-labelledby=\"kushner-title\"><header class=\"article-hero\"><div class=\"eyebrow\">GRAPHSCENE / CASE STUDY</div><h1 id=\"kushner-title\">Mapping a Complex Story with GraphScene</h1></header><div class=\"article-section\"><p>A relationship may appear in an interview, a date in an official release, and a location in a filing. Bringing those records together helps an investigator see where they connect and where more checking is needed. This showcase uses a selected set of records concerning Jared Kushner to demonstrate three views of that work in GraphScene: Graph, Timeline and Map.</p>\n<h2>Start with a relationship and follow it to the source</h2>\n<p>The Family Background graph places people, organisations, claims and sources on the same canvas. In Figure 1, the 666 Fifth Avenue example gives the reader a path from the property and Brookfield to a claim record and the associated announcement. The linked source is the place to check the scope of that claim.<sup><a href=\"#articles/mapping-a-complex-story/kushner-ref-leasehold\" aria-label=\"Reference 1\">[1]</a></sup></p>\n<figure class=\"overtime-figure\"><a href=\"assets/graphscene-kushner/G01_graph_aligned.png\" aria-label=\"Open full-size figure\"><img loading=\"lazy\" src=\"assets/graphscene-kushner/G01_graph_aligned.png\" alt=\"GraphScene graph of people, organisations, claims and source records in the G01 Family Background dataset\" width=\"2560\" height=\"1368\"></a><figcaption><strong>Figure 1.</strong> The Graph view shows family, business and public-role records in one workspace. Document nodes let readers trace individual claims to their sources, including the records associated with the 666 Fifth Avenue leasehold announcement.</figcaption></figure>\n<p>The Middle East Diplomacy graph puts interview records and records of diplomatic events in the same workspace. That makes attribution especially useful. A link to a statement attributed to Matthew Cole tells the investigator where the statement came from. An event linked to a declaration leads to a different kind of record and supports a different kind of conclusion.<sup><a href=\"#articles/mapping-a-complex-story/kushner-ref-interview\" aria-label=\"Reference 2\">[2]</a></sup><sup><a href=\"#articles/mapping-a-complex-story/kushner-ref-diplomacy\" aria-label=\"Reference 3\">[3]</a></sup></p>\n<figure class=\"overtime-figure\"><a href=\"assets/graphscene-kushner/G02_graph.png\" aria-label=\"Open full-size figure\"><img loading=\"lazy\" src=\"assets/graphscene-kushner/G02_graph.png\" alt=\"GraphScene relationship graph for G02 Middle East Diplomacy\" width=\"2560\" height=\"1368\"></a><figcaption><strong>Figure 2.</strong> GraphScene brings together people, governments, diplomatic events and source records. The graph provides a way to trace how a claim or event is documented and to distinguish attributed reporting from records of diplomatic events.</figcaption></figure>\n<h2>Put dated records in sequence</h2>\n<p>Switching to Timeline changes the question from “What is linked?” to “When does each record belong?” The G02 view shows three selected milestones and the intervals between them. The spacing shows elapsed time between records in this selection. Establishing why events followed one another would require separate evidence.<sup><a href=\"#articles/mapping-a-complex-story/kushner-ref-diplomacy\" aria-label=\"Reference 3\">[3]</a></sup></p>\n<figure class=\"overtime-figure\"><a href=\"assets/graphscene-kushner/G02_timeline_crop.png\" aria-label=\"Open full-size figure\"><img loading=\"lazy\" src=\"assets/graphscene-kushner/G02_timeline_crop.png\" alt=\"Three G02 milestones on a chronological track from 2017 to 2021\" width=\"2212\" height=\"140\"></a><figcaption><strong>Figure 3.</strong> The Timeline places three dated records from G02 in sequence. It shows a long gap between the start of the Qatar blockade and the Abraham Accords declaration, followed by a shorter interval before the Al-Ula Declaration.</figcaption></figure>\n<p>The focused Affinity Partners graph narrows the investigation to a smaller set of relationships and supporting records. The commitment record gives the investigator a specific item to inspect alongside the Senate correspondence. In that review, it matters whether a source describes a commitment, a transfer, an inquiry or a finding.<sup><a href=\"#articles/mapping-a-complex-story/kushner-ref-oversight\" aria-label=\"Reference 4\">[4]</a></sup></p>\n<figure class=\"overtime-figure\"><a href=\"assets/graphscene-kushner/G03_graph_manual.png\" aria-label=\"Open full-size figure\"><img loading=\"lazy\" src=\"assets/graphscene-kushner/G03_graph_manual.png\" alt=\"Focused GraphScene network around Affinity Partners, the Saudi PIF and Senate records\" width=\"2560\" height=\"1368\"></a><figcaption><strong>Figure 4.</strong> The focused Graph view places Affinity Partners alongside people, organisations and supporting records. The commitment record and Senate correspondence illustrate how an investigator can follow a relationship to the documents that describe it.</figcaption></figure>\n<p>The Affinity chronology adds dated records for a wider view of the sequence. A date can refer to an incorporation, an announcement, a publication or an oversight action. Inspecting the record behind each marker helps preserve those distinctions. For example, the assets-under-management milestone is dated to the report, while the period the report describes is recorded separately in the dataset.<sup><a href=\"#articles/mapping-a-complex-story/kushner-ref-chronology\" aria-label=\"Reference 5\">[5]</a></sup></p>\n<figure class=\"overtime-figure\"><a href=\"assets/graphscene-kushner/G03_timeline_crop.png\" aria-label=\"Open full-size figure\"><img loading=\"lazy\" src=\"assets/graphscene-kushner/G03_timeline_crop.png\" alt=\"Eight dated Affinity Partners records on a chronological track from 2021 to 2025\" width=\"2212\" height=\"140\"></a><figcaption><strong>Figure 5.</strong> Eight dated Affinity Partners records appear in sequence from 2021 to 2025, including incorporation, reporting on funding commitments, congressional oversight and a report on assets under management. The timeline distinguishes dates of reports and oversight actions from the dates of underlying transactions.</figcaption></figure>\n<h2>Use the Map to orient the investigation</h2>\n<p>The geography view focuses on four locations associated with the selected records. With fewer country names competing for attention, the pins show at a glance which parts of the United States and Middle East the records connect to the case study. A filing address, an oversight location and an organisation’s location each give the investigator a different lead to follow. The markers identify approximate localities. Any claim about a meeting, signing or payment venue would need its own source.<sup><a href=\"#articles/mapping-a-complex-story/kushner-ref-geography\" aria-label=\"Reference 6\">[6]</a></sup></p>\n<figure class=\"overtime-figure\"><a href=\"assets/graphscene-kushner/G03_map_country_subset.png\" aria-label=\"Open full-size figure\"><img loading=\"lazy\" src=\"assets/graphscene-kushner/G03_map_country_subset.png\" alt=\"Map with markers in Sunny Isles Beach, Washington, DC, Riyadh and Tzrifin / Nir Zvi\" width=\"2238\" height=\"1174\"></a><figcaption><strong>Figure 6.</strong> Four approximate locations show the geographic reach of the records examined in the Affinity Partners case study. Sunny Isles Beach marks a filing address, Washington, DC provides context for congressional oversight, Riyadh marks the Saudi PIF&#x27;s documented location, and Tzrifin / Nir Zvi marks the Shlomo Group&#x27;s documented location. Each pin gives readers a place to start when tracing the corresponding source records.</figcaption></figure>\n<h2>Keep the evidence attached to the interpretation</h2>\n<p>A practical workflow is to follow a link in Graph, check what its date represents in Timeline, and inspect what its location represents in Map. Return to the source before drawing a conclusion. The dataset uses provisional Admiralty ratings. The letter grades the source’s reliability and the number grades the credibility of the specific information. In the NATO scale, grade 1 calls for corroboration from other sources. A 6 means credibility cannot be assessed on the available information. A verified interview can establish what someone said while the allegation itself remains unresolved.<sup><a href=\"#articles/mapping-a-complex-story/kushner-ref-ratings\" aria-label=\"Reference 7\">[7]</a></sup></p>\n<p>The figures show selected records from a larger dataset. They illustrate how GraphScene can organise evidence and help investigators identify what to check next. The scope of each conclusion depends on what the underlying sources establish.</p>\n<h2>References</h2><ol><li id=\"kushner-ref-leasehold\"><a href=\"https://www.sec.gov/Archives/edgar/data/1001085/000117184318005734/exh_991.htm\">Brookfield’s 3 August 2018 announcement, filed with the SEC as Exhibit 99.1</a>. Brookfield describes an interest in the office condominium and identifies it as a leasehold.</li><li id=\"kushner-ref-interview\"><a href=\"https://www.democracynow.org/2026/11/2/matthew_cole_jared_kushner_book\">Democracy Now!’s interview with Matthew Cole, 2 November 2026</a>. The broadcaster’s transcript records Cole’s account.</li><li id=\"kushner-ref-diplomacy\"><a href=\"https://cirs.qatar.georgetown.edu/research/research-initiatives/gcc-crisis-qatar-and-its-neighbors/background-and-scope-project/\">Georgetown University’s background on the Qatar blockade</a>, <a href=\"https://trumpwhitehouse.archives.gov/briefings-statements/the-abraham-accords-declaration/\">the White House archive’s Abraham Accords Declaration</a>, and <a href=\"https://treaties.un.org/Pages/showDetails.aspx?objid=08000002805b2870\">the UN Treaty Collection’s Al-Ula Declaration record</a>.</li><li id=\"kushner-ref-oversight\">U.S. Senate Finance Committee, <a href=\"https://www.finance.senate.gov/ranking-members-news/wyden-probes-kushner-firm-payments-from-gulf-states-potential-fara-loophole/\">12 June 2024 inquiry announcement</a> and <a href=\"https://www.finance.senate.gov/ranking-members-news/wyden-investigation-of-kushner-firm-continues-new-letter-outlines-affinity-partners-fee-structure-lack-of-return-to-investors-questionable-deals-with-foreign-governments/\">25 September 2024 follow-up</a>. See also the <a href=\"https://oversightdemocrats.house.gov/news/press-releases/chairwoman-maloney-launches-probe-of-saudi-government-s-2-billion-investment-in\">House Oversight inquiry announcement</a> and <a href=\"https://www.pif.gov.sa/en/who-we-are/our-leadership/\">PIF’s leadership page</a>.</li><li id=\"kushner-ref-chronology\">The House Oversight announcement cited above records the January 2021 incorporation and June 2022 inquiry. The Senate records cited above document the June and September 2024 oversight milestones. The reporting milestones draw on Reuters’ coverage of <a href=\"https://finance.yahoo.com/news/jared-kushner-leave-politics-launch-160501736.html\">launch plans</a>, <a href=\"https://www.investing.com/news/stock-market-news/jared-kushner-investment-firm-affinity-raises-3-billion-in-committed-funding-2722666\">funding commitments</a> and <a href=\"https://ca.finance.yahoo.com/news/kushners-affinitys-assets-jump-4-163548441.html\">year-end 2024 assets under management</a>, and The Times of Israel’s <a href=\"https://www.timesofisrael.com/jared-kushners-saudi-backed-private-equity-fund-clinches-first-investment-in-israel/\">report on the announced Shlomo agreement</a>.</li><li id=\"kushner-ref-geography\"><a href=\"https://www.sec.gov/Archives/edgar/data/2059583/000114036125007630/0001140361-25-007630-index.htm\">SEC filing detail for Affinity Partners GP LP</a> (business address), the Senate correspondence cited above (Washington, DC), <a href=\"https://www.pif.gov.sa/-/media/project/pif-corporate/pif-corporate-site/our-financials/financial-statements/pdfs/consolidated-financial-statements-2023.pdf\">PIF’s 2023 financial statements</a> (Note 1, p. 14), and <a href=\"https://www.shlomo.co.il/_media/pdfs/shlomo_GR_2020_ENG_8.9.2020.pdf\">Shlomo Group’s corporate presentation</a> (contact section).</li><li id=\"kushner-ref-ratings\">UK Ministry of Defence, <a href=\"https://assets.publishing.service.gov.uk/media/653a4b0780884d0013f71bb0/JDP_2_00_Ed_4_web.pdf\">Joint Doctrine Publication 2-00, fourth edition</a>, Table 3.1.</li></ol></div></article></section>"}

function render(){const route=location.hash.slice(1);const isProjects=route.startsWith('projects');const isAbout=route==='about';const isKushner=route.split('/')[1]==='mapping-a-complex-story';const isNdis=route.split('/')[1]==='ndis-billing-review';const isOvertime=route.split('/')[1]==='overtime-deception';const isArticles=route==='articles'||route.startsWith('articles/');const project=route==='projects/face-finder'?'face-finder':'network';main.innerHTML=isProjects?`<div class="projects-shell">${sidebar(project)}<section class="project-main">${project==='face-finder'?faceFinder():network()}</section></div>`:isAbout?about():isArticles?(route==='articles'?articles():isKushner?mappingComplexStory():isNdis?ndisBillingReview():isOvertime?overtimeDeception():provenance()):home();document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===(isProjects?'projects':isAbout?'about':isArticles?'articles':'home');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.title=isArticles?(route==='articles'?'Articles — Matthew Ryan':isKushner?'Mapping a Complex Story with GraphScene — Matthew Ryan':isNdis?'NDIS Billing Review — Matthew Ryan':isOvertime?'The Overtime Deception — Matthew Ryan':'How We Implement Provenance — Matthew Ryan'):isAbout?'About - Matthew Ryan':isProjects?'Network Analysis Tool — Matthew Ryan':'Matthew Ryan — Investigation × Technology';if(isProjects&&project==='face-finder'){document.querySelector('#expand-face-finder').onclick=()=>openImage(faceFinderScreenshot)}if(isProjects&&project==='network'){updateSlide();document.querySelectorAll('[data-slide]').forEach(b=>b.addEventListener('click',()=>{activeSlide=Number(b.dataset.slide);updateSlide()}));document.querySelector('#previous').onclick=()=>{activeSlide=(activeSlide+slides.length-1)%slides.length;updateSlide()};document.querySelector('#next').onclick=()=>{activeSlide=(activeSlide+1)%slides.length;updateSlide()};document.querySelector('#expand-image').onclick=()=>openImage();document.querySelector('.gallery').addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();activeSlide=(activeSlide+(e.key==='ArrowRight'?1:slides.length-1))%slides.length;updateSlide()}})}}
const dialog=document.querySelector('#image-dialog');
function openImage(s=slides[activeSlide]){document.querySelector('#dialog-title').textContent=s.title;const img=document.querySelector('#full-image');img.src='assets/'+s.image;img.alt=s.alt;dialog.showModal();document.body.style.overflow='hidden';document.querySelector('.image-scroll').scrollTo(0,0)}
document.querySelector('#close-dialog').onclick=()=>dialog.close();dialog.addEventListener('close',()=>document.body.style.overflow='');dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
window.addEventListener('hashchange',()=>{if(dialog.open)dialog.close();render();const section=location.hash.split('/')[2];const target=section&&document.getElementById(section);if(target)target.scrollIntoView();else window.scrollTo(0,0);main.focus({preventScroll:true})});render();const initialSection=location.hash.split('/')[2];if(initialSection)document.getElementById(initialSection)?.scrollIntoView();
